package com.company.skillplatform.skill.application;
import static org.assertj.core.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import com.company.skillplatform.audit.application.AuditService;import com.company.skillplatform.skill.infrastructure.entity.*;import com.company.skillplatform.skill.infrastructure.repository.*;import com.company.skillplatform.user.domain.IdentityProviderType;import com.company.skillplatform.user.infrastructure.entity.IamUserEntity;import com.company.skillplatform.user.infrastructure.repository.IamUserRepository;import com.company.skillplatform.version.infrastructure.entity.SkillVersionEntity;import com.company.skillplatform.version.infrastructure.repository.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.data.domain.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.test.util.ReflectionTestUtils;
class SkillServiceTest{
 SkillRepository skills=mock(SkillRepository.class);SkillCategoryRepository categories=mock(SkillCategoryRepository.class);SkillTagRepository tags=mock(SkillTagRepository.class);SkillOwnerRepository owners=mock(SkillOwnerRepository.class);SkillTagRelationRepository relations=mock(SkillTagRelationRepository.class);SkillVersionRepository versions=mock(SkillVersionRepository.class);SkillSourceRevisionRepository revisions=mock(SkillSourceRevisionRepository.class);IamUserRepository users=mock(IamUserRepository.class);AuditService audit=mock(AuditService.class);SkillService service;IamUserEntity user;
 @BeforeEach void setup(){service=new SkillService(skills,categories,tags,owners,relations,versions,revisions,users,audit);user=new IamUserEntity(IdentityProviderType.MOCK,"u","u","h","U",null);ReflectionTestUtils.setField(user,"id",1L);when(users.findById(1L)).thenReturn(Optional.of(user));when(skills.save(any())).thenAnswer(i->{SkillEntity s=i.getArgument(0);ReflectionTestUtils.setField(s,"id",10L);return s;});when(versions.save(any())).thenAnswer(i->{SkillVersionEntity v=i.getArgument(0);ReflectionTestUtils.setField(v,"id",20L);return v;});when(tags.findAllByIdIn(any())).thenReturn(List.of());}
 @AfterEach void clearSecurity(){SecurityContextHolder.clearContext();}
 @Test void createsSearchesUpdatesAndReadsSkill(){SkillService.SkillView created=service.create(new SkillService.CreateCommand("java-tdd","Java TDD","desc",null,List.of(),List.of(),null),1L,"r");assertThat(created.skillKey()).isEqualTo("java-tdd");assertThat(created.developmentStage()).isEqualTo(com.company.skillplatform.skill.domain.DevelopmentStage.REQUIREMENT);when(skills.findBySkillKey("java-tdd")).thenAnswer(i->{SkillEntity s=new SkillEntity("java-tdd","Java TDD","desc",null,user);ReflectionTestUtils.setField(s,"id",10L);return Optional.of(s);});when(owners.existsBySkillIdAndUserId(10L,1L)).thenReturn(true);assertThat(service.get("java-tdd").displayName()).isEqualTo("Java TDD");assertThat(service.update("java-tdd",new SkillService.UpdateCommand("Updated","new",null,List.of(),null,0),1L,"r").displayName()).isEqualTo("Updated");when(skills.findAll(any(org.springframework.data.jpa.domain.Specification.class),any(Pageable.class))).thenReturn(new PageImpl<>(List.of(new SkillEntity("other","Other","d",null,user))));assertThat(service.search("oth",Pageable.unpaged())).hasSize(1);}
 @Test void opensUploadsReadsAndCancelsDraft(){SkillEntity s=new SkillEntity("java-tdd","Java TDD","d",null,user);ReflectionTestUtils.setField(s,"id",10L);when(skills.findBySkillKeyForUpdate("java-tdd")).thenReturn(Optional.of(s));when(skills.findBySkillKey("java-tdd")).thenReturn(Optional.of(s));when(owners.existsBySkillIdAndUserId(10L,1L)).thenReturn(true);SkillService.VersionView opened=service.openDraft("java-tdd",1L,"r");assertThat(opened.lifecycleStatus().name()).isEqualTo("DRAFT");assertThat(service.draft("java-tdd").id()).isEqualTo(20L);assertThat(service.markUpload("java-tdd","zip",1L,"r").sourceRevision()).isEqualTo(1);service.cancelDraft("java-tdd",0,1L,"r");assertThat(s.getActiveDraftVersion()).isNull();}
 @Test void rejectsInvalidKeyAndNonOwner(){assertThatThrownBy(()->service.create(new SkillService.CreateCommand("Bad Key","x","d",null,List.of(),List.of(),null),1L,"r")).isInstanceOf(RuntimeException.class);SkillEntity s=new SkillEntity("x","X","d",null,user);ReflectionTestUtils.setField(s,"id",3L);when(skills.findBySkillKey("x")).thenReturn(Optional.of(s));assertThatThrownBy(()->service.update("x",new SkillService.UpdateCommand("X","d",null,List.of(),null,0),2L,"r")).isInstanceOf(RuntimeException.class);}
 @Test void searchesWithStructuredFilters(){when(skills.findAll(any(org.springframework.data.jpa.domain.Specification.class),any(Pageable.class))).thenReturn(Page.empty());assertThat(service.search(null,null,null,null,null,null,null,null,Pageable.unpaged())).isEmpty();}
 @Test void searchesWithDevelopmentStageAndRejectsInvalidStage(){when(skills.findAll(any(org.springframework.data.jpa.domain.Specification.class),any(Pageable.class))).thenReturn(Page.empty());assertThat(service.search(null,null,null,null,null,null,null,"testing",Pageable.unpaged())).isEmpty();assertThatThrownBy(()->service.search(null,null,null,null,null,null,null,"nope",Pageable.unpaged())).isInstanceOf(com.company.skillplatform.common.application.BusinessException.class).hasMessageContaining("Unknown development stage");}
 @Test void developmentStageLifecycle(){assertThat(service.create(new SkillService.CreateCommand("staged","Staged","d",null,List.of(),List.of(),"backend_coding"),1L,"r").developmentStage()).isEqualTo(com.company.skillplatform.skill.domain.DevelopmentStage.BACKEND_CODING);SkillEntity s=new SkillEntity("staged","Staged","d",null,user);ReflectionTestUtils.setField(s,"id",10L);when(skills.findBySkillKey("staged")).thenReturn(Optional.of(s));when(owners.existsBySkillIdAndUserId(10L,1L)).thenReturn(true);assertThat(service.update("staged",new SkillService.UpdateCommand("Staged","d",null,List.of(),"testing",0),1L,"r").developmentStage()).isEqualTo(com.company.skillplatform.skill.domain.DevelopmentStage.TESTING);assertThat(service.update("staged",new SkillService.UpdateCommand("Staged","d",null,List.of(),null,0),1L,"r").developmentStage()).as("null stage keeps previous value").isEqualTo(com.company.skillplatform.skill.domain.DevelopmentStage.TESTING);assertThatThrownBy(()->service.update("staged",new SkillService.UpdateCommand("Staged","d",null,List.of(),"bogus",0),1L,"r")).isInstanceOf(com.company.skillplatform.common.application.BusinessException.class).hasMessageContaining("Unknown development stage");}
 @Test void developmentStageParsing(){assertThat(com.company.skillplatform.skill.domain.DevelopmentStage.fromNullable(null)).isNull();assertThat(com.company.skillplatform.skill.domain.DevelopmentStage.fromNullable(" ")).isNull();assertThat(com.company.skillplatform.skill.domain.DevelopmentStage.fromNullable("released")).isEqualTo(com.company.skillplatform.skill.domain.DevelopmentStage.RELEASED);assertThat(com.company.skillplatform.skill.domain.DevelopmentStage.fromNullable("other")).isEqualTo(com.company.skillplatform.skill.domain.DevelopmentStage.OTHER);assertThatThrownBy(()->com.company.skillplatform.skill.domain.DevelopmentStage.fromNullable("DONE")).isInstanceOf(com.company.skillplatform.common.application.BusinessException.class).hasMessageContaining("DONE");}
 @Test void legacyRowWithOtherStageIsExposed(){SkillEntity legacy=new SkillEntity("legacy","Legacy","d",null,user,com.company.skillplatform.skill.domain.DevelopmentStage.OTHER);ReflectionTestUtils.setField(legacy,"id",40L);when(skills.findBySkillKey("legacy")).thenReturn(Optional.of(legacy));assertThat(service.get("legacy").developmentStage()).isEqualTo(com.company.skillplatform.skill.domain.DevelopmentStage.OTHER);}
 @Test void explicitlyFlushesPublishedVersion(){SkillEntity skill=new SkillEntity("flush","Flush","d",null,user);SkillVersionEntity version=new SkillVersionEntity(skill,null,com.company.skillplatform.version.domain.ChangeType.INITIAL,user);service.saveVersion(version);verify(versions).saveAndFlush(version);}
 @Test void nonAdminCannotAssignOtherOwner(){assertThatThrownBy(()->service.create(new SkillService.CreateCommand("owned-skill","Owned","d",null,List.of(2L),List.of(),null),1L,"r")).isInstanceOf(com.company.skillplatform.common.application.BusinessException.class).hasMessageContaining("Only administrators");verify(skills,never()).save(any());}
 @Test void adminMayAssignOwnersAndEditNonOwnedSkill(){SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(1L,"n",List.of(()->"admin:identity")));IamUserEntity other=new IamUserEntity(IdentityProviderType.MOCK,"o","o","h","O",null);ReflectionTestUtils.setField(other,"id",2L);when(users.findById(2L)).thenReturn(Optional.of(other));assertThat(service.create(new SkillService.CreateCommand("admin-owned","Admin","d",null,List.of(2L),List.of(),null),1L,"r").skillKey()).isEqualTo("admin-owned");SkillEntity skill=new SkillEntity("other-skill","Other","d",null,other);ReflectionTestUtils.setField(skill,"id",30L);when(skills.findBySkillKey("other-skill")).thenReturn(Optional.of(skill));assertThat(service.update("other-skill",new SkillService.UpdateCommand("Changed","d",null,List.of(),null,0),1L,"r").displayName()).isEqualTo("Changed");verify(owners,never()).existsBySkillIdAndUserId(30L,1L);}
 @Test void exposesCatalogOwnersTagsAndVersionDetail(){SkillCategoryEntity category=mock(SkillCategoryEntity.class);when(category.getId()).thenReturn(4L);when(category.getCategoryKey()).thenReturn("dev");when(category.getCategoryName()).thenReturn("Development");when(category.getStatus()).thenReturn("ACTIVE");when(categories.findByStatusOrderBySortOrderAscCategoryNameAsc("ACTIVE")).thenReturn(List.of(category));SkillTagEntity tag=mock(SkillTagEntity.class);when(tag.getId()).thenReturn(5L);when(tag.getTagKey()).thenReturn("java");when(tag.getTagName()).thenReturn("Java");when(tags.findTop50ByOrderByTagNameAsc()).thenReturn(List.of(tag));when(tags.findTop50ByTagKeyContainingIgnoreCaseOrTagNameContainingIgnoreCaseOrderByTagNameAsc("jav","jav")).thenReturn(List.of(tag));assertThat(service.categories()).extracting(SkillService.CategoryView::key).containsExactly("dev");assertThat(service.tags(null)).extracting(SkillService.TagView::key).containsExactly("java");assertThat(service.tags("jav")).hasSize(1);SkillEntity skill=new SkillEntity("detail","Detail","d",category,user);ReflectionTestUtils.setField(skill,"id",10L);SkillOwnerEntity owner=new SkillOwnerEntity(skill,user,com.company.skillplatform.skill.domain.OwnerType.PRIMARY);SkillTagRelationEntity relation=new SkillTagRelationEntity(skill,tag);when(skills.findBySkillKey("detail")).thenReturn(Optional.of(skill));when(owners.findBySkillId(10L)).thenReturn(List.of(owner));when(relations.findBySkillId(10L)).thenReturn(List.of(relation));assertThat(service.get("detail").owners()).hasSize(1);SkillVersionEntity version=new SkillVersionEntity(skill,null,com.company.skillplatform.version.domain.ChangeType.INITIAL,user);ReflectionTestUtils.setField(version,"id",20L);when(versions.findById(20L)).thenReturn(Optional.of(version));assertThat(service.getVersion(20L).skillKey()).isEqualTo("detail");}
 @Test void listsVersionsAndChecksOwner(){SkillEntity skill=new SkillEntity("history","History","d",null,user);ReflectionTestUtils.setField(skill,"id",10L);SkillVersionEntity version=new SkillVersionEntity(skill,null,com.company.skillplatform.version.domain.ChangeType.INITIAL,user);when(skills.findBySkillKey("history")).thenReturn(Optional.of(skill));when(versions.findBySkillIdOrderByTimeCreatedDesc(10L)).thenReturn(List.of(version));when(owners.existsBySkillIdAndUserId(10L,1L)).thenReturn(true);assertThat(service.versions("history")).hasSize(1);service.assertOwner(version,1L);}
 @Test void primaryOwnerCanReplaceOwners(){SkillEntity skill=new SkillEntity("owned","Owned","d",null,user);ReflectionTestUtils.setField(skill,"id",10L);when(skills.findBySkillKeyForUpdate("owned")).thenReturn(Optional.of(skill));when(owners.existsBySkillIdAndUserIdAndOwnerType(10L,1L,com.company.skillplatform.skill.domain.OwnerType.PRIMARY)).thenReturn(true);when(users.findAllById(any())).thenReturn(List.of(user));when(skills.saveAndFlush(skill)).thenReturn(skill);service.replaceOwners("owned",List.of(1L),1L,0,1L,"r");verify(owners).deleteBySkillId(10L);verify(owners).save(any());}
 @Test void primaryOwnerArchivesAndRestoresSkill(){SkillEntity skill=new SkillEntity("archive-me","Archive","d",null,user);ReflectionTestUtils.setField(skill,"id",10L);when(skills.findBySkillKeyForUpdate("archive-me")).thenReturn(Optional.of(skill));when(owners.existsBySkillIdAndUserIdAndOwnerType(10L,1L,com.company.skillplatform.skill.domain.OwnerType.PRIMARY)).thenReturn(true);when(owners.existsBySkillIdAndUserId(10L,1L)).thenReturn(true);assertThat(service.archive("archive-me",0,"inactive",1L,"r").status()).isEqualTo(com.company.skillplatform.skill.domain.SkillStatus.ARCHIVED);assertThatThrownBy(()->service.openDraft("archive-me",1L,"r")).hasMessageContaining("Archived skills");assertThat(service.unarchive("archive-me",0,"resume",1L,"r").status()).isEqualTo(com.company.skillplatform.skill.domain.SkillStatus.ACTIVE);}
}
